package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.submissionfiles.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class SubmissionFilesStoreIntegrationTest {
 SubmissionStoreIntegrationTest f;SubmissionFilesStore store;
 @BeforeEach void setup(){f=new SubmissionStoreIntegrationTest();f.setup();f.open();store=new SubmissionFilesStore(f.f.source,f.store,Clock.systemUTC());}
 SubmissionFilesStore.File file(){return new SubmissionFilesStore.File(f.f.ids.next(),2,"첨부 <script>.pdf","application/pdf",42,"a".repeat(64));}
 SubmissionFilesStore.Result submit(long expected,String key,List<SubmissionFilesStore.File> refs){return store.submit(f.group,f.space,f.study,f.assignment,f.author,expected,2,key,"Answer",refs,f.f.trace);}
 SubmissionFilesStore.View get(SubmissionStore.Submission v,long version,UUID actor,boolean owner){return store.get(f.group,f.space,f.study,f.assignment,v.submissionId(),version,actor,owner);}
 void status(int code,org.junit.jupiter.api.function.Executable a){assertEquals(code,assertThrows(ResponseStatusException.class,a).getStatusCode().value());}
 @Test void attemptBundleAndSubmissionCommitWithExactPrivateProvenance()throws Exception{var refs=List.of(file(),file());var a=submit(0,f.f.key(),refs);assertTrue(a.applied());assertEquals(refs,get(a.submission(),1,f.author,false).files());var row=f.f.jdbc.queryForObject("SELECT snapshot::text FROM submission_file_bundle WHERE submission_id=?",String.class,a.submission().submissionId());var b=tools.jackson.databind.json.JsonMapper.builder().build().readValue(row,SubmissionFilesStore.Bundle.class);assertEquals(7,b.bundleId().version());assertEquals(1,b.version());assertEquals(a.submission().updatedAt(),b.createdAt());var e=SubmissionFilesEnvelopeV1.parseFrom(f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,b.bundleId()));var p=SubmissionFilesSnapshotV1.parseFrom(e.getPayload());assertEquals(2,p.getFilesCount());assertEquals(refs.getFirst().sha256(),p.getFiles(0).getSha256());assertEquals("AUTHOR_AND_OWNER",p.getAudience());assertEquals(f.author.toString(),e.getActorId());assertEquals(f.f.trace,e.getTraceId());assertEquals(2,f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid IN (?,?)",Integer.class,b.bundleId(),a.submission().submissionId()));}
 @Test void retriesReturnOriginalFilesAfterResubmissionCloseAndRestart(){String key=f.f.key();var refs=List.of(file());var a=submit(0,key,refs);var b=submit(1,f.f.key(),List.of(file()));f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);store=new SubmissionFilesStore(f.f.source,new SubmissionStore(f.f.source,f.parent.store,Clock.systemUTC()),Clock.systemUTC());var retry=submit(0,key,refs);assertFalse(retry.applied());assertEquals(a.submission(),retry.submission());assertEquals(refs,retry.files());assertEquals(b.submission(),f.store.get(f.group,f.space,f.study,f.assignment,a.submission().submissionId(),f.author,false));status(409,()->submit(0,key,List.of(file())));status(409,()->f.submit(key,0,2,"Answer"));}
 @Test void legacyAttemptsHaveEmptyFilesAndCannotReplayAsFileCommand(){String key=f.f.key();var legacy=f.submit(key,0,2,"Answer").submission();assertEquals(List.of(),get(legacy,1,f.author,false).files());status(409,()->submit(0,key,List.of(file())));var next=submit(1,f.f.key(),List.of(file()));assertEquals(List.of(),get(next.submission(),1,f.author,false).files());assertEquals(1,get(next.submission(),2,f.author,false).files().size());}
 @Test void ownerReadsRetainedFilesAndPeersOrWrongScopeCannot(){var a=submit(0,f.f.key(),List.of(file())).submission();assertEquals(get(a,1,f.author,false),get(a,1,f.f.owner,true));status(404,()->get(a,1,f.f.ids.next(),false));status(404,()->get(a,99,f.author,false));status(404,()->store.get(f.group,f.space,f.f.ids.next(),f.assignment,a.submissionId(),1,f.author,false));}
 @Test void staleOrClosedSubmissionNeverWritesBundle(){submit(0,f.f.key(),List.of(file()));status(412,()->submit(0,f.f.key(),List.of(file())));f.parent.store.state(f.group,f.space,f.study,f.assignment,f.f.owner,2,"CLOSED",f.f.trace);status(409,()->submit(1,f.f.key(),List.of(file())));assertEquals(1,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_file_bundle WHERE assignment_id=?",Integer.class,f.assignment));}
 @Test void invalidDuplicateAndTooManyMediaAreRejectedBeforeWriting(){var a=file();status(400,()->submit(0,f.f.key(),List.of()));status(400,()->submit(0,f.f.key(),List.of(a,a)));status(400,()->submit(0,f.f.key(),java.util.stream.IntStream.range(0,6).mapToObj(n->file()).toList()));status(400,()->submit(0,f.f.key(),List.of(new SubmissionFilesStore.File(a.mediaId(),1,a.filename(),a.mimeType(),42,a.sha256()))));}
 @Test void bundleOutboxFailureRollsBackAnswerAttemptAndBothEvents(){String constraint="files_fail_"+f.assignment.toString().replace("-","");f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+" CHECK(aggregatetype<>'submission-files' OR trace_id<>'"+f.f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->submit(0,f.f.key(),List.of(file())));assertNull(f.store.mine(f.group,f.space,f.study,f.assignment,f.author,true).submission());assertEquals(0,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_file_bundle WHERE assignment_id=?",Integer.class,f.assignment));}finally{f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}assertTrue(submit(0,f.f.key(),List.of(file())).applied());}
 @Test void simultaneousSameKeyRetainsOneAttemptAndOneBundle()throws Exception{String key=f.f.key();var refs=List.of(file());try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var a=pool.submit(()->{barrier.await();return submit(0,key,refs);});var b=pool.submit(()->{barrier.await();return submit(0,key,refs);});var x=a.get();var y=b.get();assertNotEquals(x.applied(),y.applied());assertEquals(x.submission(),y.submission());assertEquals(1,f.f.jdbc.queryForObject("SELECT count(*) FROM submission_file_bundle WHERE assignment_id=?",Integer.class,f.assignment));}}
}
